                            + " VALUES (?, ?, ?, 'PENDING', ?, ?)", Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, tagCode);
            ps.setString(2, fromStation);
            ps.setString(3, toStation);
            ps.setTimestamp(4, Times.toTimestamp(initiatedAt));
