        return tagService.register(request.tagCode(), request.stationCode());
    }

    /**
     * 查询标签当前持有站点。
     */
    @GetMapping("/{tagCode}")
    public TagView get(@PathVariable String tagCode) {
        return tagService.get(tagCode);
    }
}
